def count_zeros(n):
    """Counts the number of zero digits in the integer n."""
    return str(n).count('0')

# Generate all 4-digit numbers M with no zero digits
M_values = [int(str(i)) for i in range(1111, 10000) if '0' not in str(i)]

# Test N from 2 to 100
N_range = range(2, 101)

found_cases = []

for M in M_values:
    for N in N_range:
        Q = M // N
        A = count_zeros(Q)

        # We are looking for A >= 2
        if A >= 2:
            found_cases.append((M, N, Q, A))

print(f"Total cases found where A >= 2: {len(found_cases)}")
if found_cases:
    print("--- Sample Cases (M, N, Q, A) ---")
    # Print the first few results for inspection
    for i in range(min(5, len(found_cases))):
        M, N, Q, A = found_cases[i]
        print(f"M={M}, N={N}, Q={Q}, A={A}")
else:
    print("No cases found where A >= 2.")

